// sees them; the sort and the header arrows are the table's.
func (b *RegistryBrowser) rebuildTagTable() {
	tags := b.filteredMultiTags()
	frame := spinner.Dot.Frames[b.tagScanSpinnerIdx%len(spinner.Dot.Frames)]

	rows := make([]tagRow, len(tags))
	for i, t := range tags {
		imageName := multiImageName(t.RegistryURL, t.Repo, t.Tag)
		label := t.Alias
		if label == "" {
			label = t.RegistryURL
		}
		entry, scanned := b.scanCache[imageName]
		rows[i] = tagRow{
			tag:      t,
			label:    label,
			entry:    entry,
			scanned:  scanned,
			scanning: b.scanningTags[imageName],
			frame:    frame,
		}
	}

	b.tagTable.SetItems(rows)
	b.resizeTagTable()
}

// View renders the browser for the current state.
func (b *RegistryBrowser) View() string {
	switch b.state {
	case browserStateTags:
		return b.viewTags()
	default:
		return b.viewInput()
	}
}

func (b *RegistryBrowser) viewInput() string {
	var sb strings.Builder

	sb.WriteString(theme.EmptyLineBg(b.width) + "\n")
	sb.WriteString(b.renderInputField("Repository", b.repoInput.View(), brFieldRepo))
	sb.WriteString("\n\n")

	if len(b.rows) > 0 {
		sb.WriteString(theme.Bg("  ") + theme.DimStyle.Render("Registries:") + "\n")
		for i, row := range b.rows {
			focused := b.focusedField == b.brFieldReg(i)
			if row.groupSlug != "" {
				// One checkbox for the whole group, with a third state for a
				// partial selection — eight proxies are not eight keystrokes.
				sb.WriteString(theme.RenderCheckboxTri(b.groupState(row.groupSlug), row.label, focused))
			} else {
				sb.WriteString(theme.RenderCheckbox(b.selected(b.entries[row.entry]), row.label, focused))
			}
			if i < len(b.rows)-1 {
				sb.WriteString("\n")
			}
		}
		sb.WriteString("\n\n")
	}

	sb.WriteString("  ")
	sb.WriteString(theme.RenderButton("Browse Tags", b.focusedField == b.brFieldSubmit(), "primary"))

	return sb.String()
}

func (b *RegistryBrowser) renderInputField(label, value string, fieldIdx int) string {
	var labelStr string
	if b.focusedField == fieldIdx {
		labelStr = theme.KeyStyle.Render(theme.IconCircleSmall + " " + label + " " + theme.IconChevronRight)
	} else {
		labelStr = theme.Bg("  " + label + " " + theme.IconChevronRight)
	}
	return labelStr + "\n  " + value
}

// viewTags renders the tag table. The search says so in the footer, with a
// spinner (LoadingLabel), and an empty table stays a table (Rule 139) — the
// count lives in GetHeaderInfo's "Tags" field.
func (b *RegistryBrowser) viewTags() string {
	return b.tagTable.View()
}

// LoadingLabel names what the browser is fetching, for the OCI view's footer.
// The second result is false when nothing is in flight.
func (b *RegistryBrowser) LoadingLabel() (string, bool) {
	if b.state == browserStateTags && b.pendingSearches > 0 {
		return "Searching registries...", true
	}
	return "", false
}

// FilterIsVisible returns true when the tag filter bar should be shown in the footer.
func (b *RegistryBrowser) FilterIsVisible() bool {
	return b.state == browserStateTags && (b.filterActive || b.filterInput.Value() != "" || !b.registryFilter.isEmpty())
}

// FilterBarView renders the filter bar (2 lines) for display in the footer.
func (b *RegistryBrowser) FilterBarView(width int) string {
	borderStyle := lipgloss.NewStyle().Foreground(theme.ColorViewportBorder).Background(theme.ColorBackground)

	var left string
	if b.filterActive {
		left = theme.KeyStyle.Render("/") + theme.Bg(" ") + b.filterInput.View()
	} else if b.filterInput.Value() != "" {
		left = theme.DimStyle.Render("/ ") + theme.KeyStyle.Render(b.filterInput.Value())
	} else {
		left = theme.DimStyle.Render("/ filter…")
	}

	if !b.registryFilter.isEmpty() {
		left += theme.Bg("  ") + theme.KeyStyle.Render("["+b.registryFilterLabel()+"]")
	}

	inner := theme.Bg(" ") + left
	paddedInner := theme.PadWithBg(inner, width-2)
	contentLine := borderStyle.Render("│") + paddedInner + borderStyle.Render("│")
	bottomBorder := borderStyle.Render("└" + strings.Repeat("─", width-2) + "┘")
	return contentLine + "\n" + bottomBorder
}

// viewStatus is gone with browserStateStatus (§3.60). It was a
// theme.SpinnerMessage filling the panel — the shape Rule 139 keeps out of a
// table body — and what it announced is now a row in the Images tab.
package ociresources

import (
	"time"

	"github.com/anthnel/devdesk/internal/cache"
)

// AddRegistryTags incorporates results from one registry into the combined tag list.
// Always decrements pendingSearches, even on error (tags will be nil).
func (b *RegistryBrowser) AddRegistryTags(entryKey, registryURL, alias, repo string, tags []string) {
	// Floored: a duplicate or late response would otherwise drive the counter
	// negative, and the next search would start from that base — IsSearching()
	// would stay false while requests were genuinely in flight, so the spinner
	// never showed.
	if b.pendingSearches > 0 {
		b.pendingSearches--
	}
	for _, tag := range tags {
		b.tags = append(b.tags, MultiRegistryTag{
			EntryKey:    entryKey,
			RegistryURL: registryURL,
			Alias:       alias,
			Repo:        repo,
			Tag:         tag,
		})
	}
	if b.state == browserStateTags {
		b.rebuildTagTable()
	}
}

// SetMultiTagsMeta stores last-updated metadata for tags belonging to one entry.
//
// Keyed on the entry, not the host: several entries share one host once a
// registry is a host plus a repo prefix, so a URL would stamp one proxy's dates
// onto every proxy of that instance (§3.18).
func (b *RegistryBrowser) SetMultiTagsMeta(entryKey string, meta map[string]time.Time) {
	for i := range b.tags {
		if b.tags[i].EntryKey != entryKey {
			continue
		}
		if t, ok := meta[b.tags[i].Tag]; ok {
			b.tags[i].UpdatedAt = t
		}
	}
	if b.state == browserStateTags {
		b.rebuildTagTable()
	}
}

// SetTagScanningSet replaces the in-progress scans the tag rows decorate.
//
// A set rather than one name at a time: the source is the registry snapshot,
// which says what is running rather than what changed, and reconciling a whole
// answer against per-name edits is how the two drift.
func (b *RegistryBrowser) SetTagScanningSet(scanning map[string]bool) {
	b.scanningTags = scanning
	if b.state == browserStateTags {
		b.rebuildTagTable()
	}
}

// HasSelectedTagScanResults returns true when the selected tag has cached scan results.
func (b *RegistryBrowser) HasSelectedTagScanResults() bool {
	name := b.selectedImageName()
	if name == "" {
		return false
	}
	_, ok := b.scanCache[name]
	return ok
}

// SetScanCache stores the model's scan cache for CVE column display.
func (b *RegistryBrowser) SetScanCache(sc map[string]cache.ImageScanEntry) {
	b.scanCache = sc
	if b.state == browserStateTags {
		b.rebuildTagTable()
	}
}

// SetOperationError, SetOperationSuccess and OperationImageName went with the
// status screen (§3.60): the browser is closed by the time a pull answers, and
// the answer goes to the footer and the Images list.

// selectedImageName returns the full image reference for the focused table row.
func (b *RegistryBrowser) selectedImageName() string {
	t := b.getSelectedMultiTag()
	if t == nil {
		return ""
	}
	return multiImageName(t.RegistryURL, t.Repo, t.Tag)
}

// getSelectedMultiTag returns the MultiRegistryTag under the cursor, or nil.
//
// It used to replay the filter and the sort to map the cursor back to a tag,
// with nothing tying that ordering to the one the rows were built from. The
// table keeps the ordered slice it drew, so the two cannot disagree.
func (b *RegistryBrowser) getSelectedMultiTag() *MultiRegistryTag {
	row, ok := b.tagTable.Selected()
	if !ok {
		return nil
	}
	return &row.tag
}
package ociresources

import (
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/indicator"
)

// ociKinds are the operations whose activity or remembered failure an Images
// row shows: a scan or a pull, whoever started it (D5).
var ociKinds = []jobs.Kind{jobs.KindScan, jobs.KindPull}

// rowActivity resolves what one Images row says about its activity, read from
// the router snapshot against the context it carries. The identity is the raw
// reference, never a canonical form. A removal in flight is this view's own
// observation: it is reported as Running with its label.
func (m Model) rowActivity(r imageRow) components.RowActivity {
	q := components.RowQuery{
		Runs: m.jobs, Failures: m.failures, Context: m.contextName,
		Target: jobs.TargetKey(r.RawName), Kinds: ociKinds,
	}
	if label, ok := m.imageTable.BusyLabel(r.Image.ID); ok {
		q.Observed = indicator.Running
		q.ObservedText = label
	}
	return components.DescribeRow(q)
}

// scanRunning reports whether a scan of the image is running now in the
// current context. A queued scan is not running.
func (m Model) scanRunning(name string) bool { return m.runningOn(name, jobs.KindScan) }

// pullRunning reports whether a pull of the image is running now in the
// current context. A queued pull is not running.
func (m Model) pullRunning(name string) bool { return m.runningOn(name, jobs.KindPull) }

func (m Model) runningOn(name string, kind jobs.Kind) bool {
	for _, a := range jobs.ActiveOn(m.jobs, m.contextName, name, kind) {
		if a.Item.State == jobs.ItemRunning {
			return true
		}
	}
	return false
}

// ActivityTables returns the read-only face of the view's table, keyed by the
// name the activity-column guard (internal/app) knows it by. Tests only.
func (m Model) ActivityTables() map[string]datatable.ActivityTable {
	return map[string]datatable.ActivityTable{
		"oci/images":     &m.imageTable,
		"oci/networks":   &m.networkTable,
		"oci/volumes":    &m.volumeTable,
		"oci/registries": &m.registryTable,
	}
}
			if g := indicator.Glyph(s, on); g != "" && strings.Contains(line, g) {
				return true
			}
		}
	}
	return false
}

func TestNoImageCellCarriesASpinnerFrame(t *testing.T) {
	m := ociSnapshot(t, ociCtx, []jobs.Run{
		ociRun(jobs.KindScan, ociCtx, jobs.ItemRunning, imgRef),
		ociRun(jobs.KindPull, ociCtx, jobs.ItemRunning, "web:v3"),
		ociRun(jobs.KindPull, ociCtx, jobs.ItemRunning, imgNewRef),
	}, nil)
	m = feed(t, m, jobs.FrameMsg{Frame: "ZZ", RenderedFrame: "ZZ", Blink: true})
	m.imageTable.MarkBusy(imageRowByName(t, m, "cache:v2").Image.ID, "Removing cache:v2")
	if view := m.imageTable.View(); hasSpinnerFrame(view) || strings.Contains(view, "ZZ") {
		t.Errorf("a spinner frame reached the Images table:\n%s", view)
	}
	for _, row := range m.imageTable.Table().Rows() {
		for _, cell := range row {
			if hasSpinnerFrame(cell) {
				t.Errorf("cell %q carries a spinner frame", cell)
			}
		}
	}
}

func TestARunningScanHoldsTheScannedCellDim(t *testing.T) {
	m := ociSnapshot(t, ociCtx, []jobs.Run{ociRun(jobs.KindScan, ociCtx, jobs.ItemRunning, imgRef)}, nil)
	r := imageRowByName(t, m, imgRef)
	if !r.ScanRunning || r.PullRunning {
		t.Fatalf("ScanRunning/PullRunning = %v/%v, want true/false", r.ScanRunning, r.PullRunning)
	}
	col := imageColByTitle(t, "Scanned")
	if got := col.Cell(r); got != "scanning" {
		t.Errorf("Scanned cell = %q, want the static %q", got, "scanning")
	}
	if got, want := col.Style(r).GetForeground(), theme.DimStyle.GetForeground(); got != want {
		t.Errorf("Scanned style = %v, want DimStyle %v", got, want)
	}
	if id := imageColByTitle(t, "ID").Cell(r); id != shortID(r.Image.ID) {
		t.Errorf("ID cell = %q on a scanning row, want %q", id, shortID(r.Image.ID))
	}
}

func TestARunningPullHoldsTheIDCellDim(t *testing.T) {
	m := ociSnapshot(t, ociCtx, []jobs.Run{ociRun(jobs.KindPull, ociCtx, jobs.ItemRunning, "web:v3")}, nil)
	r := imageRowByName(t, m, "web:v3")
	if !r.PullRunning || r.ScanRunning {
		t.Fatalf("PullRunning/ScanRunning = %v/%v, want true/false", r.PullRunning, r.ScanRunning)
	}
	col := imageColByTitle(t, "ID")
	if got := col.Cell(r); got != "pulling" {
		t.Errorf("ID cell = %q, want the static %q", got, "pulling")
	}
	if got, want := col.Style(r).GetForeground(), theme.DimStyle.GetForeground(); got != want {
		t.Errorf("ID style = %v, want DimStyle %v", got, want)
	}
}

// A queued scan is not running: the row keeps its date and shows no "scanning".
func TestAQueuedScanKeepsItsPreviousScannedCell(t *testing.T) {
	m := ociSnapshot(t, ociCtx, []jobs.Run{ociRun(jobs.KindScan, ociCtx, jobs.ItemQueued, imgRef)}, nil)
	r := imageRowByName(t, m, imgRef)
	if r.ScanRunning {
		t.Error("a queued scan holds the Scanned cell")
	}
	if got, want := imageColByTitle(t, "Scanned").Cell(r), timeAgo(r.Entry.ScannedAt); got != want || got == "scanning" {
		t.Errorf("queued Scanned cell = %q, want the previous %q", got, want)
	}
	if got := imageColByTitle(t, "ID").Cell(r); got == "pulling" {
		t.Error("a scan turned the ID cell into pulling")
	}
}

func TestAPullPlaceholderRowShowsTheRunningDot(t *testing.T) {
	m := ociSnapshot(t, ociCtx, []jobs.Run{ociRun(jobs.KindPull, ociCtx, jobs.ItemRunning, imgNewRef)}, nil)
	m = feed(t, m, jobs.FrameMsg{Blink: true})
	r := imageRowByName(t, m, imgNewRef)
	if r.Activity.State != indicator.Running || !r.PullRunning {
		t.Fatalf("placeholder Activity/PullRunning = %v/%v, want Running/true", r.Activity.State, r.PullRunning)
	}
	if line := imageLine(t, m, "new:v1"); !strings.Contains(line, glyphDot) {
		t.Errorf("the placeholder row has no running dot:\n%s", line)
	}
}

func TestARemovalBlinksTheDotWithThePhase(t *testing.T) {
	m := loadedModel(t)
	r := imageRowByName(t, m, imgRef)
	m.imageTable.MarkBusy(r.Image.ID, "Removing "+imgRef)
	m.updateImageTable()
	for _, tc := range []struct {
		blink bool
		want  string
	}{{true, glyphDot}, {false, glyphHollow}} {
		next := feed(t, m, jobs.FrameMsg{Blink: tc.blink})
		line := imageLine(t, next, imgRef)
		if !strings.Contains(line, tc.want) {
			t.Errorf("blink=%v: row lacks %q:\n%s", tc.blink, tc.want, line)
		}
		if !strings.Contains(line, shortID(r.Image.ID)) {
			t.Errorf("blink=%v: the removing row lost its ID:\n%s", tc.blink, line)
		}
		if hasSpinnerFrame(line) {
			t.Errorf("blink=%v: spinner frame on the removing row:\n%s", tc.blink, line)
		}
	}
}

func TestAFrameStampsNothingOnTheRows(t *testing.T) {
	m := ociSnapshot(t, ociCtx, []jobs.Run{ociRun(jobs.KindScan, ociCtx, jobs.ItemRunning, imgRef)}, nil)
	a := imageRowByName(t, feed(t, m, jobs.FrameMsg{Blink: true}), imgRef)
	b := imageRowByName(t, feed(t, m, jobs.FrameMsg{Blink: false}), imgRef)
	if a.Activity != b.Activity {
		t.Errorf("the phase leaked into the row: %+v vs %+v", a.Activity, b.Activity)
	}
}

// BlinkingView: the router asks the view on screen whether a row blinks.
func TestWantsBlinkFollowsTheRowsThatBlink(t *testing.T) {
	var _ interface{ WantsBlink() bool } = Model{}
	t0 := time.Now()
	idle := loadedModel(t)
	if idle.WantsBlink() {
		t.Error("an idle table wants the blink")
	}
	if !ociSnapshot(t, ociCtx, []jobs.Run{ociRun(jobs.KindScan, ociCtx, jobs.ItemRunning, imgRef)}, nil).WantsBlink() {
		t.Error("a running scan does not ask for the blink")
	}
	if !ociSnapshot(t, ociCtx, []jobs.Run{ociRun(jobs.KindPull, ociCtx, jobs.ItemRunning, imgNewRef)}, nil).WantsBlink() {
		t.Error("a running pull placeholder does not ask for the blink")
	}
	if ociSnapshot(t, ociCtx, []jobs.Run{ociRun(jobs.KindScan, ociCtx, jobs.ItemQueued, imgRef)}, nil).WantsBlink() {
		t.Error("a queued scan blinks")
	}
	if ociSnapshot(t, ociCtx, nil, []jobs.Failure{ociFailure(jobs.KindScan, ociCtx, imgRef, t0)}).WantsBlink() {
		t.Error("a remembered failure blinks")
	}
	busy := loadedModel(t)
	id := busy.imageTable.Items()[0].Image.ID
	busy.imageTable.MarkBusy(id, "Removing")
	busy.updateImageTable()
	if !busy.WantsBlink() {
		t.Error("a busy image row does not ask for the blink")
	}
	busy.imageTable.ClearBusy(id)
	busy.updateImageTable()
	if busy.WantsBlink() {
		t.Error("the blink outlived the removal")
	}
}

// Visible columns, by title, indicator written as "●". A dropped column has
// width 0 (Rule 116).
func visibleImageColumns(m Model) []string {
	var out []string
	for _, c := range m.imageTable.Table().Columns() {
		if c.Width <= 0 {
			continue
		}
		title, _, _ := strings.Cut(c.Title, " ") // "Name ▲" -> "Name"
		if c.Title == "" {
			title = glyphDot
		}
		out = append(out, title)
	}
	return out
}

func TestImageColumnsDropInTheNewOrder(t *testing.T) {
	tests := []struct {
		width int
		want  []string
	}{
		{60, []string{"●", "ID", "Name", "Update"}},
		{70, []string{"●", "ID", "Name", "Update", "Secrets", "C"}},
		{80, []string{"●", "ID", "Name", "Update", "Secrets", "C", "H", "M"}},
		{90, []string{"●", "ID", "Name", "Update", "Sig", "Secrets", "C", "H", "M", "L"}},
		{100, []string{"●", "ID", "Name", "Update", "Sig", "Secrets", "C", "H", "M", "L"}},
		{103, []string{"●", "ID", "Name", "Update", "Sig", "Secrets", "C", "H", "M", "L"}},
		{104, []string{"●", "ID", "Name", "Update", "Sig", "Disk", "Secrets", "C", "H", "M", "L"}},
		{119, []string{"●", "ID", "Name", "Update", "Sig", "Disk", "Secrets", "C", "H", "M", "L"}},
		{120, []string{"●", "ID", "Name", "Update", "Sig", "Disk", "Content", "Secrets", "C", "H", "M", "L"}},
		{135, []string{"●", "ID", "Name", "Update", "Sig", "Disk", "Content", "Secrets", "C", "H", "M", "L"}},
		{136, []string{"●", "ID", "Name", "Update", "Sig", "Disk", "Content", "Secrets", "C", "H", "M", "L", "Scanned"}},
	}
	for _, tt := range tests {
		m := feed(t, loadedModel(t), testutil.Resize(tt.width, 30))
		if got := visibleImageColumns(m); !slices.Equal(got, tt.want) {
			t.Errorf("width %d: visible columns = %v, want %v", tt.width, got, tt.want)
		}
		if got, want := m.imageTable.RenderedWidth(), tt.width-2; got != want {
			t.Errorf("width %d: the line spans %d, want %d (Rule 116)", tt.width, got, want)
		}
	}
}

func TestImageColumnsFitTheWidthWithTheCFGColumn(t *testing.T) {
	cfg := testConfig()
	cfg.Scan.Categories.Misconfig.Enabled = true
	for _, width := range []int{60, 70, 80, 90, 110, 140, 200} {
		m := feed(t, New(cfg), tea.WindowSizeMsg{Width: width, Height: 30}, ImagesListMsg{Images: imageFixtures()})
		if got, want := m.imageTable.RenderedWidth(), width-2; got != want {
			t.Errorf("width %d with CFG: the line spans %d, want %d", width, got, want)
		}
		if got := visibleImageColumns(m); got[0] != glyphDot || got[1] != "ID" {
			t.Errorf("width %d with CFG: columns start %v, want [● ID …]", width, got)
		}
	}
	m := feed(t, New(cfg), tea.WindowSizeMsg{Width: 200, Height: 30}, ImagesListMsg{Images: imageFixtures()})
	got := visibleImageColumns(m)
	if i := slices.Index(got, "CFG"); i < 0 || got[i-1] != "L" || got[i+1] != "Scanned" {
		t.Errorf("at 200 the CFG column is misplaced: %v", got)
	}
}

// The real removal flow marks the row busy in Update() without rebuilding the
// rows; WantsBlink must still follow it (no manual updateImageTable here).
func TestWantsBlinkStartsWhenARemovalStartsAndStopsWhenItFails(t *testing.T) {
	m := removeSelected(t, loadedModel(t))
	img := m.imageTable.Items()[0]
	if !m.imageTable.IsBusy(img.Image.ID) {
		t.Fatal("precondition: the removal was not marked busy")
	}
	if !m.WantsBlink() {
		t.Error("WantsBlink is false right after the removal started")
	}
	m = feed(t, m, ImageActionMsg{Action: "remove", ID: img.Image.ID, Name: img.RawName, Err: errors.New("image is in use")})
	if m.imageTable.IsBusy(img.Image.ID) {
		t.Fatal("precondition: the busy marker survived the failure")
	}
	if m.WantsBlink() {
		t.Error("WantsBlink stays true after a failed rmi (blink stuck)")
	}
}

// Failure half, isolated: the rows were rebuilt while busy (setup only), then
// the real ImageActionMsg error path runs with no manual rebuild.
func TestWantsBlinkStopsAfterAFailedRmi(t *testing.T) {
	m := removeSelected(t, loadedModel(t))
	img := m.imageTable.Items()[0]
	m.updateImageTable() // setup: put the blinking state on the rows
	if !m.WantsBlink() {
		t.Fatal("setup: a busy row does not ask for the blink")
	}
	m = feed(t, m, ImageActionMsg{Action: "remove", ID: img.Image.ID, Name: img.RawName, Err: errors.New("image is in use")})
	if m.WantsBlink() {
		t.Error("WantsBlink stays true after a failed rmi (blink stuck)")
	}
}

