package ociresources

import (
	"log"
	"time"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/registrymgr"
	"github.com/anthnel/devdesk/internal/trust"
)

// openMultiRegistryBrowser opens the multi-registry browser (triggered by 'b' on Images tab).
func (m Model) openMultiRegistryBrowser() (tea.Model, tea.Cmd) {
	if len(m.registries) == 0 {
		return m, m.footer.Warn("No registries configured — add one in the Registries tab")
	}
	// Config plus cache, read here and now: no network, no waiting, no state
	// that ignores esc (D13).
	m.registryBrowser = newRegistryBrowser(m.registries, m.groupCache, m.browserDeselected, m.width-2, m.height)
	m.registryBrowser.SetScanCache(m.scanCache)
	return m, nil
}

// closeMultiRegistryBrowser drops the browser, remembering what the user
// unchecked so the next visit opens on the same selection.
func (m Model) closeMultiRegistryBrowser() (tea.Model, tea.Cmd) {
	if m.registryBrowser == nil {
		return m, nil
	}
	deselected := m.registryBrowser.Deselected()
	m.registryBrowser = nil

	m.browserDeselected = make(map[string]bool, len(deselected))
	for _, key := range deselected {
		m.browserDeselected[key] = true
	}
	return m, saveBrowserSelectionCmd(deselected)
}

// handleMultiRegistryTagsLoaded incorporates tag results from one registry into the browser.
func (m Model) handleMultiRegistryTagsLoaded(msg MultiRegistryTagsLoadedMsg) (tea.Model, tea.Cmd) {
	if m.registryBrowser == nil {
		return m, nil
	}
	if msg.Err != nil {
		log.Printf("ERROR [oci_resources] registry tags %s from %s: %v", msg.Repo, msg.RegistryURL, msg.Err)
		m.registryBrowser.AddRegistryTags(msg.EntryKey, msg.RegistryURL, msg.Alias, msg.Repo, nil)
		return m, nil
	}
	m.registryBrowser.SetScanCache(m.scanCache)
	m.registryBrowser.AddRegistryTags(msg.EntryKey, msg.RegistryURL, msg.Alias, msg.Repo, msg.Tags)
	return m, loadMultiRegistryTagsMetaCmd(msg.EntryKey, msg.RegistryURL, msg.Repo)
}

// handleMultiRegistryTagsMeta stores tag metadata for one registry in the browser.
func (m Model) handleMultiRegistryTagsMeta(msg MultiRegistryTagsMetaMsg) (tea.Model, tea.Cmd) {
	if m.registryBrowser == nil {
	// Another view asks for an image to be shown (keymap.Jump) — see focus.go.
	case FocusImageRequestMsg:
		return m.handleFocusImage(msg)

	case ImageScanStartingMsg:
		return m.handleImageScanStarting(msg)

	case ImageScanFinishedMsg:
		return m.handleImageScanFinished(msg)

	case ScanRequestMsg:
		return m.handleScanRequest(msg)

	case jobs.ChangedMsg:
		return m.handleJobsChanged(msg)

	case jobs.FrameMsg:
		return m.handleFrameMsg(msg)

	case spinner.TickMsg:
		var cmds []tea.Cmd
		// Only a load turns this spinner: a row's state is drawn by the activity
		// column, which jobs.FrameMsg animates.
		if m.loading || m.loadingNets || m.loadingVols || m.loadingRegs {
			var cmd tea.Cmd
			m.spinner, cmd = m.spinner.Update(msg)
			// A tab's load is reported in the footer, so the frame has to reach
			// it — a spinner stuck on frame zero reads as a hang.
			m.footer.SetSpinnerFrame(m.spinner.View())
			cmds = append(cmds, cmd)
		}
		if m.registryBrowser != nil {
			var cmd tea.Cmd
			m.registryBrowser, cmd = m.registryBrowser.Update(msg)
			if cmd != nil {
				cmds = append(cmds, cmd)
			}
		}
		if len(cmds) > 0 {
			return m, tea.Batch(cmds...)
		}

	case RefreshTickMsg:
		return m, tea.Batch(fetchImages(), loadScanCache(), fetchNetworks(), fetchVolumes())

	case ImagesListMsg:
		return m.handleImagesList(msg)

	case ImageUpdatesCheckedMsg:
		return m.handleImageUpdatesChecked(msg)

			cmd = m.registryTable.Update(msg)
			return m, cmd
		}
	}
	return m, nil
}

// handleKeyMsg processes keyboard input with priority chain
func (m Model) handleKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	// Priority 0: registry browser
	if m.registryBrowser != nil {
		var cmd tea.Cmd
		m.registryBrowser, cmd = m.registryBrowser.Update(msg)
		return m, cmd
	}
	// Priority 1: launch form
	if m.launchForm != nil {
		var cmd tea.Cmd
		m.launchForm, cmd = m.launchForm.Update(msg)
		return m, cmd
	}
	// Priority 2: resource creation form
	if m.resourceForm != nil {
		var cmd tea.Cmd
		m.resourceForm, cmd = m.resourceForm.Update(msg)
		return m, cmd
	}
	// Priority 2.5: registry form
	if m.registryForm != nil {
		var cmd tea.Cmd
		m.registryForm, cmd = m.registryForm.Update(msg)
		return m, cmd
	}
	// Priority 3: network inspect overlay
	if m.networkInspectForm != nil {
		return m.handleNetworkInspectKeyMsg(msg)
	}
	// Priority 4: whichever modal is open
	if m.confirmModal != nil {
		var cmd tea.Cmd
		m.confirmModal, cmd = m.confirmModal.Update(msg)
		}
		return append(base,
			shortcut.Shortcut{Key: keymap.New, Description: "New registry", Disabled: !m.registryCreate().Enabled()},
			shortcut.Shortcut{Key: keymap.Edit, Description: "Edit registry", Disabled: !entry.Enabled()},
			shortcut.Shortcut{Key: keymap.Auth, Description: "Log in or out", Disabled: !entry.Enabled()},
			shortcut.Shortcut{Key: keymap.Delete, Description: "Remove", Disabled: !entry.Enabled()},
			shortcut.Shortcut{Key: "→", Description: "Show members", Disabled: !m.registryDrillIn().Enabled()},
			shortcut.Shortcut{Key: "←", Description: "Back to registries", Disabled: !m.registryDrillOut().Enabled()},
			shortcut.Shortcut{Key: "ctrl+r", Description: refresh},
			shortcut.Shortcut{Key: "?", Description: "Help"},
		)
	}

	base = append(base,
		shortcut.Shortcut{Key: "ctrl+r", Description: "Refresh"},
		shortcut.Shortcut{Key: "?", Description: "Help"},
	)
	return base
}

// View renders the view (Rule 112: forms in viewport, modals centered)
func (m Model) View() string {
	// Priority 0: registry browser (viewport)
	if m.registryBrowser != nil {
		return m.registryBrowser.View()
	}
	// Priority 1: launch form (viewport)
	if m.launchForm != nil {
		return m.launchForm.View()
	}
	// Priority 2: resource creation form (viewport)
	if m.resourceForm != nil {
		return m.resourceForm.View()
	}
	// Priority 3: registry form (viewport)
	if m.registryForm != nil {
		return m.registryForm.View()
	}
	// Priority 4: whichever modal is open (centered)
	if modal := m.modalView(); modal != "" {
		return lipgloss.Place(
			m.width, m.height,
			lipgloss.Center, lipgloss.Center,
			modal,
			lipgloss.WithWhitespaceBackground(theme.ColorBackground),
		)
	}
	// Priority 5: network inspect form (viewport)
	if m.networkInspectForm != nil {
		return m.networkInspectForm.View()
	}
	// Priority 6: normal view by active tab
	return m.renderNormalView()
}

// renderNormalView renders the active tab's content
func (m Model) renderNormalView() string {
	switch m.activeTab {
	case tabNetworks:
		return m.renderNetworksView()
	case tabVolumes:
		return m.renderVolumesView()
	case tabRegistries:
		return m.renderRegistriesView()
	default:
		return m.renderImagesView()
		st.Text = m.inlineSecretLine()
	}
	// Only a detail whose dot moves replaces the spinner; a failed row's is fixed.
	st.Spinner = len(jobs.Unfinished(m.jobs)) > 0 && (!moving || st.Detail.IsZero())
	return st
}

// inlineSecretLine says why the selected registry's Logged cell is a warning:
// its password sits in the engine's auth file, base64 encoded, which is not
// encryption (§3.68). A state rather than a message — it holds for as long as
// the row is selected, not for three seconds.
func (m Model) inlineSecretLine() string {
	if m.activeTab != tabRegistries || m.authFile == "" {
		return ""
	}
	url := ""
	if reg := m.getSelectedRegistry(); reg != nil {
		url = reg.URL
	} else if group := m.drilledGroup(); group != nil {
		url = group.URL
	}
	if m.registryLoginStatus[url] != docker.LoginInline {
		return ""
	}
	return "Password stored unencrypted in " + m.authFile + " — configure a credential helper"
}

// formStatus is the status while a form or the browser has the viewport. The
// tables behind them are not on screen, so their loads say nothing here; the
// browser's own search does.
func (m Model) formStatus() sharedcomponents.Status {
	if m.registryBrowser != nil {
		if text, ok := m.registryBrowser.LoadingLabel(); ok {
			return sharedcomponents.Status{Text: text, Spinner: true}
		}
	}
	if m.networkInspectForm != nil && m.networkInspectForm.loading {
		return sharedcomponents.Status{Text: "Loading containers...", Spinner: true}
	}
	return sharedcomponents.Status{}
}

// loadingLabel names what the active tab is fetching, or reports that it is
// settled. Only the tab on screen answers: a volumes load says nothing while
// the Images tab is showing.
func (m Model) loadingLabel() (string, bool) {
	switch m.activeTab {
	case tabImages:
		return "Loading images...", m.loading && len(m.images) == 0
	case tabNetworks:
		return "Loading networks...", m.loadingNets && len(m.networkTable.Items()) == 0
	case tabVolumes:
		return "Loading volumes...", m.loadingVols && len(m.volumeTable.Items()) == 0
	}
	return "", false
}

// renderRegistryBreadcrumb renders the drill-down trail below the table when
// the Registries tab has entered a group (Rules 111, 123). Breadcrumb mode: it
// is not navigable, the level you are on is highlighted and the one above is
// dimmed. Empty at the top level, where there is no trail to show.
func (m Model) renderRegistryBreadcrumb(width int) string {
	group := m.drilledGroup()
	if group == nil {
		return ""
	}
	tabs := []theme.TabItem{
		{Label: "Registries"},
		{Label: browserAlias(*group)},
	}
	return theme.PadWithBg(theme.Bg(" ")+theme.RenderTabs(tabs, 1), width)
}

// renderTabBar renders the tab bar below the viewport (Rule 123)
func (m Model) renderTabBar(width int) string {
	tabs := []theme.TabItem{
		{Label: theme.ContainerEngineIcon(engine.Current().Name) + " Images"},
		{Label: theme.IconNetwork + " Networks"},
		{Label: theme.IconVolume + " Volumes"},
		{Label: theme.IconServer + " Registries"},
	}
	return theme.PadWithBg(theme.Bg(" ")+theme.RenderTabs(tabs, int(m.activeTab)), width)
}

// GetTitle returns the view title
func (m Model) GetTitle() string {
	base := theme.ContainerEngineIcon(engine.Current().Name) + " OCI Resources"
	if m.registryBrowser != nil {
		title := base + " " + theme.IconChevronRight + " Registry Browser"
		if m.registryBrowser.state == browserStateTags && m.registryBrowser.repoInput.Value() != "" {
			title += " " + theme.IconChevronRight + " " + m.registryBrowser.repoInput.Value()
		}
		if !m.registryBrowser.registryFilter.isEmpty() {
			title += " [" + m.registryBrowser.registryFilterLabel() + "]"
		}
		return title
